<script lang="ts">
 import {onMount} from 'svelte';
 import {Box,Search,FolderOpen,AlertTriangle,ExternalLink,Download,Check} from 'lucide-svelte';
 import {call,asset} from './api';
 import {statuses,visibleRows,indexedRows,needsReview,type Summary,type Row,type Settings} from './model';
 let {summary,folder,settings,preview=false,onerror,onopen}:{summary:Summary|null;folder:string;settings:Settings;preview?:boolean;onerror:(e:unknown)=>void;onopen:()=>void}=$props();
 let query=$state(''),filter=$state(''),page=$state(0),selected=$state<number|null>(null),frame=$state(''),frameKind=$state('preview'),viewer=$state<HTMLIFrameElement>(),loaded=$state(false),pendingFocus=false;
 const all=$derived(summary?indexedRows(summary):[]),rows=$derived(visibleRows(all,query,filter)),pageRows=$derived(rows.slice(page*100,page*100+100)),current=$derived(selected===null?null:all[selected]);
 const review=$derived(all.filter(needsReview)),alignment=$derived((summary?.alignment||{}) as {applied?:boolean;translation_B_to_A_mm?:number[];rotation_B_to_A?:number[][];status?:string});
 const complete=$derived(summary?.analysis_complete===true&&review.length===0);
 const palette=$derived((summary?.colors_hex||{}) as Record<string,string>);
 function color(status:string){return palette[status]||settings.palette[(status==='RENAMED'?'SAME':status).toLowerCase()]||'#94a3b8';}
 function number(value:unknown,unit='mm'){return typeof value==='number'&&Number.isFinite(value)?`${value.toLocaleString('pl',{maximumFractionDigits:4})} ${unit}`:'Nie podano';}
 function pair(r:Row){return `A[${r.a_index??'—'}] → B[${r.b_index??'—'}]`;}
 function command(action:string,focus=false){if(loaded&&frameKind==='preview')viewer?.contentWindow?.postMessage({type:'dscompare:command',action,record_index:selected,focus,pair:focus},'*');}
 async function show(kind='preview',focus=false){try{pendingFocus=focus;if(frame&&frameKind===kind){command('select',focus);return;}loaded=false;const path=await call<string>('artifact_path',{folder,name:kind==='preview'?'PODGLAD_KOLOROW_3D.html':'RAPORT.html'});frameKind=kind;frame=asset(path);}catch(e){onerror(e)}}
 async function output(name:string){try{await call('open_artifact',{folder,name})}catch(e){onerror(e)}}
 function select(r:Row){selected=Number(r.record_index);command('select');}
 function setFilter(value:string){filter=filter===value?'':value;page=0;command(filter==='CHANGES'?'changes':'all');}
 function receive(e:MessageEvent){if(e.source!==viewer?.contentWindow||!e.data)return;
  if(e.data.type==='dscompare:ready'){if(frameKind!=='preview'){show('preview',true);return;}loaded=true;viewer?.contentWindow?.postMessage({type:'dscompare:command',action:'configure',embedded:true},'*');if(selected!==null)command('select',pendingFocus);pendingFocus=false;}
  if(e.data.type==='dscompare:selected'&&e.data.record_index===null&&loaded)selected=null;
  if(e.data.type==='dscompare:selected'&&Number.isInteger(e.data.record_index)&&all[e.data.record_index]){selected=e.data.record_index;let index=rows.findIndex(r=>r.record_index===selected);if(index<0){filter='';query='';index=selected??0;}page=Math.floor(index/100);}
 }
 onMount(()=>{window.addEventListener('message',receive);return()=>window.removeEventListener('message',receive)});
 let lastFolder='',lastPreview=false;
 $effect(()=>{if(folder!==lastFolder){lastFolder=folder;frame='';selected=null;query='';filter='';page=0;if(folder&&summary?.preview_3d)show();}else if(preview&&!lastPreview&&folder)show();lastPreview=preview;});
</script>
<div class="page-heading"><div><span class="eyebrow">PRZEGLĄD REWIZJI CAD</span><h1>Wyniki analizy</h1><p class="result-path">{folder||'Otwórz folder wyników lub wykonaj porównanie.'}</p></div><button onclick={()=>folder?output('folder'):onopen()}><FolderOpen size={16}/>{folder?'Folder wyników':'Otwórz wyniki'}</button></div>
{#if summary}
 <section class="analysis-summary panel" aria-label="Podsumowanie analizy"><span class:warning={!complete} class="analysis-badge">{#if complete}<Check size={16}/>{:else}<AlertTriangle size={16}/>{/if}{complete?'Analiza pełna':summary.analysis_complete===false?'Analiza częściowa':'Zakres wymaga sprawdzenia'}</span><span>A: <strong>{summary.solids_A??'—'}</strong> · B: <strong>{summary.solids_B??'—'}</strong></span><span>Tolerancja: {number(summary.tolerance_mm)}</span><button onclick={()=>setFilter('DIAGNOSTIC')}>Do sprawdzenia: {review.length}</button></section>
 {#if !complete}<div class="banner warning" role="note">Niepotwierdzone pozycje wymagają sprawdzenia. Nie określono dla nich ilości materiału dodanego ani usuniętego.</div>{/if}
 <details class="panel alignment-panel" open><summary>Położenie całego złożenia i ruch części</summary>{#if alignment.translation_B_to_A_mm}<div class="alignment-values"><strong>Wyrównanie B → A</strong>{#each ['X','Y','Z'] as axis,i}<span>{axis}: {number(alignment.translation_B_to_A_mm[i])}</span>{/each}<span>{alignment.applied?'Zastosowano':'Nie zastosowano'}</span></div>{:else}<p>Nie zastosowano wyrównania całego złożenia.</p>{/if}<p>Wektory części opisują ruch A → B{alignment.applied?' po wyrównaniu złożeń':' w położeniu użytym do analizy'}. W podglądzie możesz przełączyć położenie B oraz porównać A i B ze wspólną kamerą.</p></details>
 <div class="stats">{#each ['SAME','MOVED','CHANGED','ADDED','REMOVED','UNCERTAIN'] as status}<button class:chosen={filter===status} onclick={()=>setFilter(status)} style={`--status:${color(status)}`}><span>{statuses[status]}</span><strong>{(summary.statuses?.[status]||0)+(status==='SAME'?(summary.statuses?.RENAMED||0):0)}</strong></button>{/each}</div>
 <div class="toolbar"><button onclick={()=>show('report')}><ExternalLink size={15}/>Raport HTML / PDF</button><button onclick={()=>show()}><Box size={15}/>Podgląd 3D</button><button disabled={summary.step_ready===false} onclick={()=>output('POROWNANIE_KOLORY.step')}><Download size={15}/>Kolorowy STEP</button>{#each [['ZMIANY.csv','Zmiany CSV'],['BOM_A.csv','BOM A'],['BOM_B.csv','BOM B']] as [name,label]}<button disabled={name.startsWith('BOM')&&(summary.full_bom===false||summary.bom_csv===false)} onclick={()=>output(name)}>{label}</button>{/each}<button class:chosen={filter==='CHANGES'} onclick={()=>setFilter('CHANGES')}>Tylko zmiany</button><button class:chosen={filter==='DIAGNOSTIC'} onclick={()=>setFilter('DIAGNOSTIC')}>Diagnostyka części ({review.length})</button></div>
 <div class="review-workspace">
  <section class="part-browser panel" aria-label="Lista części"><div class="search"><Search size={15}/><input aria-label="Szukaj części w wynikach" placeholder="Nazwa, numer, uwagi…" bind:value={query} oninput={()=>page=0}/></div><select aria-label="Filtr wyników" bind:value={filter} onchange={()=>page=0}><option value="">Wszystkie pozycje</option><option value="CHANGES">Tylko zmiany</option><option value="DIAGNOSTIC">Wymagające sprawdzenia</option>{#each Object.entries(statuses) as [key,label]}<option value={key}>{label}</option>{/each}</select><p>{rows.length} pozycji</p><div class="part-list">{#each pageRows as row}<button class:selected={selected===row.record_index} onclick={()=>select(row)} aria-pressed={selected===row.record_index}><span class="status-tag" style={`--status:${color(row.status)}`}>{statuses[row.status]||row.status}</span><strong>{row.name_b||row.name_a||pair(row)}</strong><small>{pair(row)}</small>{#if row.blocked_operation_operand}<small>Operacja zakończona błędem</small>{/if}</button>{/each}{#if !rows.length}<p>Brak pasujących pozycji.</p>{/if}</div><div class="pagination"><button disabled={!page} onclick={()=>page--}>←</button><span>{page+1} / {Math.max(1,Math.ceil(rows.length/100))}</span><button disabled={(page+1)*100>=rows.length} onclick={()=>page++}>→</button></div></section>
  <section class="review-viewer viewer"><div class="viewer-bar"><span>{frameKind==='report'?'Raport HTML':'Podgląd 3D · wybór połączony z listą'}</span>{#if frameKind==='report'}<button onclick={()=>show()}>Wróć do 3D</button>{/if}</div>{#if frame}<iframe bind:this={viewer} title={frameKind==='preview'?'Podgląd modeli 3D':'Raport porównania'} src={frame} sandbox="allow-scripts allow-downloads"></iframe>{:else}<div class="empty"><Box size={36}/><p>Podgląd jest dostępny, jeśli został wygenerowany podczas analizy.</p><button onclick={()=>show()}>Otwórz podgląd 3D</button></div>{/if}</section>
  <aside class="part-details panel" aria-label="Szczegóły części">{#if current}<span class="eyebrow">POZYCJA {Number(current.record_index)+1}</span><h2>{statuses[current.status]||current.status}</h2><dl><dt>Poprzednia A</dt><dd>{current.name_a||'—'}</dd><dt>Nowa B</dt><dd>{current.name_b||'—'}</dd><dt>Identyfikatory</dt><dd>{pair(current)}</dd><dt>Ścieżka A</dt><dd>{current.path_a||'—'}</dd><dt>Ścieżka B</dt><dd>{current.path_b||'—'}</dd></dl><h3>Ruch części A → B</h3><dl>{#each [['X','delta_x'],['Y','delta_y'],['Z','delta_z'],['Odległość środka','distance_mm']] as [label,key]}<dt>{label}</dt><dd>{number(current[key])}</dd>{/each}<dt>Obrót dopasowania</dt><dd>{number(current.rotation_deg,'°')}</dd></dl><h3>Weryfikacja</h3><p>{needsReview(current)?'Wymaga sprawdzenia':current.confidence||'Status z zapisanego wyniku'}</p><p class="diagnostic-reason">{String(current.diagnostic_reason||current.note||'Brak dodatkowych uwag.')}</p>{#if current.blocked_operation_operand}<div class="banner warning">Element uczestniczył w operacji zakończonej błędem. To nie przesądza o poprawności pozostałych elementów.</div>{/if}<button onclick={()=>show('preview',true)}><Box size={15}/>Pokaż część w 3D</button><button onclick={()=>{selected=null;command('clear')}}>Wyczyść wybór</button><details><summary>Dane szczegółowe</summary><pre>{JSON.stringify(current,null,2)}</pre></details>{:else}<Box size={28}/><h2>Wybierz część</h2><p>Kliknij pozycję na liście lub geometrię w podglądzie, aby zobaczyć nazwę, ruch i przyczynę ostrzeżenia.</p>{/if}</aside>
 </div>
 <div class="legend-panel"><span>Wspólna legenda statusów</span>{#each ['SAME','MOVED','CHANGED','ADDED','REMOVED','UNCERTAIN'] as status}<span><i style={`background:${color(status)}`}></i>{statuses[status]}</span>{/each}</div>
{:else}<div class="empty"><Box size={44}/><h2>Wyniki pojawią się tutaj</h2><button onclick={onopen}>Otwórz folder wyników</button></div>{/if}
